// Capture image errors before dynamically rendered logos start loading.
document.addEventListener('error', (event) => {
  const image = event.target;
  if (!(image instanceof HTMLImageElement)) return;
  if (!image.closest('.site-logo, .recently-logo, .search-result-logo, .activity-logo, .recent-change-logo, .logo')) return;
  const fallback = document.createElement('span');
  fallback.className = 'logo-fallback';
  fallback.textContent = (image.alt || 'W').replace(/ logo$/i, '').trim().slice(0, 1).toUpperCase() || 'W';
  fallback.setAttribute('aria-hidden', 'true');
  image.replaceWith(fallback);
}, true);

